'use strict';

// MODULES //

var linspace = require( '@stdlib/array/base/linspace' );
var rempio2f = require( './../lib' );


// MAIN //

var x = linspace(0.0, 100.0, 100);
var y = [0.0]; // Single-element array for the remainder
var n;
var i;

for (i = 0; i < x.length; i++) {
	n = rempio2f(x[i], y);
	console.log('%d - %dπ/2 = %d', x[i], n, y[0]);
}
